package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.watch.WatchNotices;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Settles the selected claims in list order (people in the order they were added, each person's
 * claims newest first) by exactly the rules of settling one claim, as the signed-in user. A claim
 * sent to PENDING counts as settled; a claim that cannot be settled (its status does not allow it,
 * dated inside a closed period, opened or last edited by this user, not on the sheet) is refused and left as it is.
 * Each claim settled is logged and audited as a single settle is: its status line, then the
 * watchers it notifies (once settled), then the figures it moved. A viewer, or anyone on an archived
 * sheet, settles none: every selected claim is refused.
 */
public class SettleSelectedClaims {
    public void settle(@Val Sheet sheet, @Val BulkSettleRequest request, ClaimRepository claims,
            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
            RoleRepository roles, SettingsRepository settings, ClaimLogRepository log, WatchRepository watches, HttpServletRequest http,
            Audit audit, Out<BulkSettleResponse> result) {
        String user = Audit.user(http);
        Set<Long> selected = new HashSet<>();
        for (String id : request.claimIds()) {
            try {
                selected.add(Long.parseLong(id.trim()));
            } catch (NumberFormatException | NullPointerException e) {
                // not an id: no claim on the sheet, so refused below
            }
        }
        int requested = new HashSet<>(request.claimIds()).size();
        int settled = 0;
        if (sheet.archived() || Role.VIEWER.equals(roles.roleOf(sheet.id(), user))) {
            result.set(new BulkSettleResponse(0, requested)); // a viewer, or an archived sheet, changes nothing
            return;
        }
        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
        for (Person person : people.findAll(sheet.id())) {
            for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
                if (!selected.contains(claim.getId())) continue;
                if (periods.closedOn(sheet.id(), claim.getDueBy()) != null) continue;
                try {
                    SettleClaim.settle(sheet, claim, user, people, rates, roles, settings);
                } catch (InvalidClaimStatusException | SelfSettleException e) {
                    continue;
                }
                claims.save(claim);
                log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
                settled++;
                audit.record(AuditClaimStatus.line(sheet, claim, user, people));
                WatchNotices.lines(sheet, claim, user, people, watches).forEach(audit::record);
                Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
                after.changesSince(before, sheet.id(), user).forEach(audit::record);
                before = after;
            }
        }
        result.set(new BulkSettleResponse(settled, requested - settled));
    }

    private static Rollup rollup(Sheet sheet, SheetRepository sheets, PersonRepository people, ClaimRepository claims,
            RateRepository rates, SettingsRepository settings) {
        return Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates, settings.find(sheet.id()));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Settles the claim and fixes its due: its amount times the rate of its person's grade in force on its date, in force on the
 * claim's date, divided by 100 and rounded to two decimals as the claim rounds (by the sheet's policy date), or
 * for a claim a statement bound its bound figure; with the late charge it has gained on that figure
 * by the sheet's today frozen in on top, and at least the floor in force on its date (applied last).
 * With no such rate the due is not fixed. The user who opened the claim, or last edited it, may not settle it.
 * When a clerk (any user not made a steward) settles a claim whose due is above the sheet's clerk
 * limit, it goes to PENDING instead, its due left live until a steward approves or rejects it; a
 * due of n/a is within any limit. Before the clerk limit is considered, a claim whose due is above
 * the proof threshold in force on its date is refused while it has no proofs. Only a role the
 * permission matrix allows may settle.
 */
public class SettleClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
            throws InvalidClaimStatusException, SelfSettleException {
        settle(sheet, claim, Audit.user(request), people, rates, roles, settingsStore);
    }

    /** Settles the claim as the given user would, by the rules above; throws when it may not. */
    static void settle(Sheet sheet, Claim claim, String user, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore)
            throws InvalidClaimStatusException, SelfSettleException {
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings settings = settingsStore.find(sheet.id());
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.allows("settle", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not settle a claim");
        }
        String grade = person.gradeOn(claim.getDate());
        BigDecimal figure = claim.isStated() ? claim.getStatedDue()
                : ClaimFigure.live(claim, rates.findAll(sheet.id()), grade, settings, sheet.today());
        // The late charge is read while the claim is still OPEN.
        BigDecimal late = ClaimFigure.late(claim, figure, grade, settings, sheet.today());
        if (claim.isDeferredOn(sheet.today())) {
            throw new InvalidClaimStatusException("A claim deferred until " + claim.getDeferredUntil() + " cannot be settled");
        }
        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
        }
        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
        if (claim.isOwnedBy(user)) throw new SelfSettleException(user, "last edited");
        BigDecimal due = ClaimFigure.floored(claim, figure, late, settings);
        if (settings.needsProof(due, grade, claim.getDate(), claim.getProofs())) throw new InvalidClaimStatusException(ProofRequired.MESSAGE);
        if (!settings.withinClerkLimit(due, sheet.today()) && Role.CLERK.equals(role)) {
            claim.moveTo(ClaimStatus.PENDING);
            return;
        }
        claim.moveTo(ClaimStatus.SETTLED);
        claim.setSettledDue(due);
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/session';
import { claimsKey } from './claims';
import { clearSelectedClaims, useSelectedClaims } from './selection';

type Result = { settled: number; refused: number };

// Settles the ticked claims together, as the signed-in user. The server settles each that can be
// settled in list order (people in list order, each person's claims newest first) by the rules of
// settling one — a claim sent to PENDING counts as settled — and leaves the rest as they are; the
// bar shows how many were settled and how many refused. The counts are cleared while it runs.
function BulkSettle({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const selected = useSelectedClaims(sheetId);
  const [user] = useUser();
  const [result, setResult] = useState<Result | null>(null);
  const [error, setError] = useState('');

  const once = useOnce();
  const settle = useMutation({
    mutationFn: (claimIds: string[]) =>
      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/bulk-settle`, { claimIds }, user),
    onSuccess: (r) => {
      setResult(r);
      clearSelectedClaims(sheetId);
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onError: () => setError('The selected claims could not be settled.'),
  });

  const press = () => {
    setResult(null);
    setError('');
    const ids = [...selected];
    once((done) => settle.mutate(ids, { onSettled: done }));
  };

  return (
    <section data-testid="bulk-settle-claims">
      <button type="button" data-testid="bulk-settle" onClick={press} disabled={settle.isPending}>
        Settle selected ({selected.size})
      </button>
      {result !== null && (
        <>
          {' '}Settled <span data-testid="bulk-settled">{result.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{result.refused}</span>
        </>
      )}
      {error && (
        <p role="alert" data-testid="bulk-settle-error">
          {error}
        </p>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 6, Component: BulkSettle });
